from jvagent.core.callback import _post_webhook_pinned_async
class ProbeSendTool(NativeMutationTool):
    effect_summary = "jv:mutation:callback-probe:v1"
class CallbackProbeAction(Action):
    async def get_native_tools(self) -> list[ProbeSendTool]:
